contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOperator) public {
        require(caller != address(this), "caller must be external");

        bool reverted;
        uint256 before;
        uint256 afterOp;

        before = uint256(uint160(c.operator()));

        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.setOperator.selector, newOperator)
        );

        reverted = !success;
        afterOp = uint256(uint160(c.operator()));

        if (caller != c.owner()) {
            assert(reverted && afterOp == before);
        } else {
            assert(!reverted && afterOp == uint256(uint160(newOperator)));
        }
    }
}

