contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newValue) public {
        require(caller != address(this), "test caller must not be the test contract");
        require(newValue != address(0), "new value must be nonzero");

        address ownerBefore = c.owner();
        address operatorBefore = c.operator();

        require(caller != ownerBefore && caller != operatorBefore, "caller must be neither owner nor operator");

        // Both calls are top-level state-changing operations on c, made by msg.sender = InvMutTest.
        // Since InvMutTest is neither owner nor operator (required above), both must revert.
        bool transferOwnerReverted;
        try c.transferOwnership(newValue) {
            transferOwnerReverted = false;
        } catch {
            transferOwnerReverted = true;
        }

        bool setOperatorReverted;
        try c.setOperator(newValue) {
            setOperatorReverted = false;
        } catch {
            setOperatorReverted = true;
        }

        address ownerAfter = c.owner();
        address operatorAfter = c.operator();

        // General rule: unauthorized callers cannot change ownership or operator; and if both attempts revert,
        // the owner and operator remain exactly as before.
        assert(
            (transferOwnerReverted && setOperatorReverted) &&
            ownerAfter == ownerBefore &&
            operatorAfter == operatorBefore
        );
    }
}

