contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint256 amount) public payable {
        // Precondition: caller is not the operator and not the owner, so the
        // onlyOperatorOrOwner modifier must reject the call.
        require(caller != c.operator() && caller != c.owner(), "caller must be unauthorized");

        // Drive the call through an intermediary contract so that msg.sender
        // for c is this test contract, not the run() caller. We need the
        // unauthorized sender's identity to be used for the call on c, so we
        // cannot use a helper. Instead, this test relies on the harness
        // making msg.sender equal to the test contract; to obtain an
        // unauthorized caller we set the operator and owner to fixed
        // addresses not equal to msg.sender.
        //
        // The state changes below are top-level calls on c.
        c.setOperator(address(0xdeadbeef));
        c.setRewardsRecipient(address(0));

        // Ensure there is no balance in c, so any withdrawal must revert
        // before transfer logic is reached. We only make view calls and
        // state-changing setup here.

        bool reverted;
        try c.withdrawAndUnwrap(amount, false, address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: when the caller (msg.sender) is neither the operator
        // nor the owner, withdrawAndUnwrap must revert because of the
        // onlyOperatorOrOwner modifier.
        assert(reverted);
    }

    receive() external payable {}
}

