        uint256 recoveryAmount,
        bool asOwner
    ) public payable {
        address ownerBefore = c.owner();
        bool callerIsOwner = msg.sender == ownerBefore;
        require(callerIsOwner == asOwner, "caller must match asOwner");

        uint32 oldPId = c.cvxPoolInfo()[2];
        address oldToken = c.cvxPoolInfo()[0];
        address oldRewards = c.cvxPoolInfo()[1];
        address oldOperator = c.operator();
