        bool didSucceed;

        if (asOwner) {
            c.setCvxPoolInfo(pId, token, rewards);
            c.setOperator(newOperator);
            c.setRewardsRecipient(recipient);
            c.setCvxPoolInfo(uint32(1), address(0x1), address(0x2));

            reverted = false;
            didSucceed = true;
        } else {
            try c.setCvxPoolInfo(pId, token, rewards) {
                _;
                reverted = false;
                didSucceed = true;
            } catch {
                reverted = true;
                didSucceed = false;
            }
        }

        if (asOwner) {
            assert(c.cvxPoolInfo()[2] == uint32(1) && c.cvxPoolInfo()[0] == address(0x1) && c.cvxPoolInfo()[1] == address(0x2));
            assert(c.operator() == newOperator);
            assert(c.rewardsRecipient() == recipient);
        } else {
            assert(reverted == !didSucceed);
            assert(c.cvxPoolInfo()[2] == oldPId);
            assert(c.cvxPoolInfo()[0] == oldToken);
            assert(c.cvxPoolInfo()[1] == oldRewards);
            assert(c.operator() == oldOperator);
            assert(c.rewardsRecipient() == oldRecipient);
        }
    }
