        address token = idx == 0 ? rewardToken0 : rewardToken1;

        // Read the balance before the deciding call, but this token must not be clpToken.
        uint256 beforeBalance = 0;
        if (token != address(0)) {
            beforeBalance = IERC20(token).balanceOf(address(c));
