contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(amount > 0, "amount must be positive");

        // Ensure the caller is the operator (the constructor set operator to this test contract's deployer/address).
        require(c.operator() == address(this), "test is not operator");

        // Record the allowance c has granted to the booster before the deposit.
        uint256 beforeAllowance = IERC20(c.clpToken()).allowance(address(c), address(c.booster()));

        // Make the deciding call; depositAndStake is only callable by the operator.
        // It increases allowance and calls booster.deposit, but the allowance side effect is
        // observable regardless of whether the booster call succeeds or reverts.
        bool reverted;
        try c.depositAndStake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the allowance granted to the booster must have increased by exactly amount.
        // SafeERC20.safeIncreaseAllowance performs an approve with oldAllowance + amount, so if
        // the call did not revert, the allowance equals beforeAllowance + amount. Even on revert
        // in the external booster call, the approve txn has already been mined, so allowance
        // remains increased by amount (no rollback between the two calls).
        uint256 afterAllowance = IERC20(c.clpToken()).allowance(address(c), address(c.booster()));
        assert(afterAllowance == beforeAllowance + amount);
    }

    receive() external payable {}
}

