    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool claim, address to) public payable {
        require(to != address(0), "recipient must be non-zero");

        uint256 beforeBalance = c.clpToken().balanceOf(address(c));
        require(beforeBalance >= amount, "contract must hold enough clpToken");

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.clpToken().balanceOf(address(c));

        assert(!reverted && afterBalance + amount == beforeBalance);
    }

    receive() external payable {}
}

