contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool claim, bool sendToOperator) public payable {
        address ownerAddr = c.owner();
        require(ownerAddr == address(this), "test must be owner");

        address clp = address(c.clpToken());
